CREATE FUNCTION public.save_customer_catalog_order(ids uuid[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'super_admin')) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF cardinality(ids)>300 THEN RAISE EXCEPTION 'Too many items'; END IF; UPDATE public.item_icons i SET customer_order=(o.n-1)*10 FROM unnest(ids) WITH ORDINALITY o(id,n) WHERE i.id=o.id AND (i.customer_only OR i.user_id=auth.uid()); END $$; REVOKE ALL ON FUNCTION public.save_customer_catalog_order(uuid[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_customer_catalog_order(uuid[]) TO authenticated,service_role;